import{c as r,Q as s,j as d,g as t,n as e}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"同步机制","description":"","frontmatter":{},"headers":[{"level":1,"title":"同步机制","slug":"同步机制"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/同步机制.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/同步机制.md"}'),o={name:"guide/编程指南/编程模型/AI-Core-SIMT编程/同步机制.md"};function c(l,a,n,p,i,h){return s(),d("div",null,[...a[0]||(a[0]=[t("h1",{id:"同步机制",tabindex:"-1"},[e("同步机制 "),t("a",{class:"header-anchor",href:"#同步机制","aria-label":'Permalink to "同步机制"'},"​")],-1),t("p",null,"SIMT是一种单指令多线程的编程模式，其异步编程模型旨在通过多线程并发执行达到内存操作加速的目的。在这一编程模型中，线程作为执行计算或操作内存的最小抽象单位，其操作是相互独立的。然而，在某些应用场景中，需要支持线程间的同步，或防止不同线程对同一内存区域的读写操作引发的数据竞争。为此，Ascend C提供了相应的同步接口，这些接口允许开发者根据需求选择合适的同步机制，以确保异步操作的正确性和性能。",-1),t("p",null,[e('<table><thead align="left"><tr><th class="cellrowborder" valign="top" width="19.88%"><p>接口名</p> </th> <th class="cellrowborder" valign="top" width="80.12%"><p>功能说明</p> </th> </tr> </thead> <tbody><tr><td class="cellrowborder" valign="top" width="19.88%"><p><a href="'),t("a",{href:"https://gitcode.com/munanhw/asc-devkit/blob/master/docs/api/context/asc_syncthreads.md",target:"_blank",rel:"noreferrer"},"https://gitcode.com/munanhw/asc-devkit/blob/master/docs/api/context/asc_syncthreads.md"),e('">asc_syncthreads</p> </td> <td class="cellrowborder" valign="top" width="80.12%"><p>等待当前线程块内所有线程代码都执行到该函数位置。</p> </td> </tr> <tr><td class="cellrowborder" valign="top" width="19.88%"><p><a href="'),t("a",{href:"https://gitcode.com/munanhw/asc-devkit/blob/master/docs/api/context/asc_threadfence.md",target:"_blank",rel:"noreferrer"},"https://gitcode.com/munanhw/asc-devkit/blob/master/docs/api/context/asc_threadfence.md"),e('">asc_threadfence</p> </td> <td class="cellrowborder" valign="top" width="80.12%"><p>用于保证不同线程对同一份全局、共享内存的访问过程中，写入操作的时序性。它不会阻塞线程，仅保证内存操作的可见性顺序。</p> </td> </tr> <tr><td class="cellrowborder" valign="top" width="19.88%"><p>asc_threadfence_block</p> </td> <td class="cellrowborder" valign="top" width="80.12%"><p>用于协调同一线程块（Thread Block）内线程之间的内存操作顺序，<span>确保某一线程在asc_</span>threadfence_block()<span>之前</span><span>的所有内存操作（读写），对</span><span>同一线程块内的其他线程</span><span>是可见的</span>。</p> </td> </tr> </tbody> </table>')],-1)])])}const _=r(o,[["render",c]]);export{m as __pageData,_ as default};
